\setlength{\abovedisplayskip}{3pt}
\setlength{\belowdisplayskip}{3pt}
\setlength{\jot}{1pt}
\begin{equation}
\begin{aligned}
 \varphi( \mathcal{X}_2) & =\sum_{m=1}^{M} (2\alpha_m\sqrt{lp_m}-\alpha_m^{2}\tilde{ r}_m )
  &\quad - \sum_{m=1}^{M}\beta_m(\Upsilon_m-\tilde{ r}_m) - \sum_{m=1}^{M} \phi_{m}(\|\boldsymbol{w}_m\|^2  - 1).
\end{aligned}
\end{equation}
\endgroup
Let $\mathcal{X}_{2} {=} \{ \beta_m, \boldsymbol{w}_m, \phi_{m}\}$ denote the set of optimization and dual variables, where $\{ \beta_m,\forall m\}$ are the dual variables associated with constraint \eqref{eq26a}, $\{ \phi_{m},\forall m\}$ are the dual variables associated with constraint \eqref{eq11a}.
 The partial derivatives of $ \varphi( \mathcal{X}_{2})$ with respect to $\boldsymbol{w}_m$ are given by:
 \begingroup
\small
\setlength{\abovedisplayskip}{3pt}
\setlength{\belowdisplayskip}{3pt}
\setlength{\jot}{1pt}
\begin{equation}
\begin{aligned}
 \frac{\partial  \varphi( \mathcal{X}_{2})}{\partial \boldsymbol{w}_m} & = -\phi_{m}\boldsymbol{w}^*_m -B\alpha_m^{2}\mathcal{G}_m\sqrt{p_m }\boldsymbol{h}^*_m\mathcal{I}_m 
 &+B\alpha_m^{2}\mathcal{G}_m|\mathcal{I}_m|^2  (\sum\limits_{j=1}^{ M} p_j  \boldsymbol{h}^*_m\boldsymbol{h}^{\text{T}}_m+\sigma^2\boldsymbol{I})\boldsymbol{w}^*_m  
  &+B\beta_m\mathcal{G}_m\sqrt{p_m }\boldsymbol{h}^*_m\mathcal{I}_m 
  &-B\beta_m\mathcal{G}_m|\mathcal{I}_m|^2  (\sum\limits_{j=1}^{ M} p_j  \boldsymbol{h}^*_m\boldsymbol{h}^{\text{T}}_m+\sigma^2\boldsymbol{I})\boldsymbol{w}^*_m.
\end{aligned}
\end{equation}
\endgroup
According to the first-order optimality condition, the optimal solution to Problem $\mathbf{(P4.3)}$ is derived by setting the derivative of $\varphi(\mathcal{X}_{2})$ to zero, which yields the optimal transmit power as
\begingroup
\small
\setlength{\abovedisplayskip}{3pt}
\setlength{\belowdisplayskip}{3pt}
\setlength{\jot}{1pt}
\begin{align}
&(\boldsymbol{w}_m)^{\mathrm{opt}} =\nonumber
&\frac{(\alpha_m^{2}-\beta_m)B\mathcal{G}_m\sqrt{p_m }\boldsymbol{h}_m\mathcal{I}_m }{B\mathcal{G}_m|\mathcal{I}^*_m|^2  (\sum\limits_{j=1}^{ M} p_j  \boldsymbol{h}^*_m\boldsymbol{h}^{\text{T}}_m+\sigma^2\boldsymbol{I})(\beta_m-\alpha_m^{2})+\phi_{m}\boldsymbol{I}}.
\end{align}
\endgroup
\end{proof}
\section{Proof of Proposition \ref{prop1}}
\label{App3}
\begin{proof}
Let us define $\{\boldsymbol{F}^{(l)},\boldsymbol{P}^{(l)},\boldsymbol{W}^{(l)},\boldsymbol{X}^{(l)}\}$ as the variables updated in the $l$-th iteration, with $\Phi (\cdot)$ denoting the objective function of problem \textbf{P1}. Initially, given $\{\boldsymbol{P}^{(l)},\boldsymbol{W}^{(l)},\boldsymbol{X}^{(l)}\}$, we obtain the optimal computation allocation $\boldsymbol{F}^{(l+1)}$ from problem \textbf{P2}. This results in the following reduction in the objective value:
\begingroup
\small
\setlength{\abovedisplayskip}{3pt}
\setlength{\belowdisplayskip}{3pt}
\setlength{\jot}{1pt}
\begin{equation}
\begin{aligned}
&\Phi (\boldsymbol{F}^{(l)},\boldsymbol{P}^{(l)}, \boldsymbol{W}^{(l)}, \boldsymbol{X}^{(l)})
&\geq \Phi (\boldsymbol{F}^{(l+1)},\boldsymbol{P}^{(l)}, \boldsymbol{W}^{(l)},\boldsymbol{X}^{(l)}).\label{e36}
\end{aligned}
\end{equation}
\endgroup
Then, for fixed $\{\boldsymbol{F}^{(l+1)}, \boldsymbol{X}^{(l)}\}$, the transmit power $ \boldsymbol{P}^{(l+1)}$  and the receive beamforming $ \boldsymbol{W}^{(l+1)}$ are determined by solving problem \textbf{P3} via Algorithm \ref{algorithm1}, which implies
\begingroup
\small
\setlength{\abovedisplayskip}{3pt}
\setlength{\belowdisplayskip}{3pt}
\setlength{\jot}{1pt}
\begin{equation}
\begin{aligned}
&\Phi (\boldsymbol{F}^{(l+1)},\boldsymbol{P}^{(l)}, \boldsymbol{W}^{(l)}, \boldsymbol{X}^{(l)}) 
&\geq \Phi (\boldsymbol{F}^{(l+1)},\boldsymbol{P}^{(l+1)}, \boldsymbol{W}^{(l+1)},\boldsymbol{X}^{(l)}).\label{e38}
\end{aligned}
\end{equation}
\endgroup
In the last step, the MA positions $ \boldsymbol{X}^{(l+1)}$ are refined by solving problem \textbf{P5} based on $\{\boldsymbol{F}^{(l+1)},\boldsymbol{P}^{(l+1)}, \boldsymbol{W}^{(l+1)}\}$. Consequently,
\begingroup
\small
\setlength{\abovedisplayskip}{3pt}
\setlength{\belowdisplayskip}{3pt}
\setlength{\jot}{1pt}
\begin{equation}
\begin{aligned}
&\Phi (\boldsymbol{F}^{(l+1)},\boldsymbol{P}^{(l+1)}, \boldsymbol{W}^{(l+1)}, \boldsymbol{X}^{(l)}) 
&\geq \Phi (\boldsymbol{F}^{(l+1)},\boldsymbol{P}^{(l+1)}, \boldsymbol{W}^{(l+1)},\boldsymbol{X}^{(l+1)}).\label{e39}
\end{aligned}
\end{equation}
\endgroup
From \eqref{e36}-\eqref{e39}, the overall relationship is derived as:
\begingroup
\small
\setlength{\abovedisplayskip}{3pt}
\setlength{\belowdisplayskip}{3pt}
\setlength{\jot}{1pt}
\begin{equation}
\begin{aligned}
&\Phi (\boldsymbol{F}^{(l)},\boldsymbol{P}^{(l)}, \boldsymbol{W}^{(l)}, \boldsymbol{X}^{(l)}) 
&\geq\Phi (\boldsymbol{F}^{(l+1)},\boldsymbol{P}^{(l+1)}, \boldsymbol{W}^{(l+1)},\boldsymbol{X}^{(l+1)}).\label{e40}
\end{aligned}
\end{equation}
\endgroup
Equation \eqref{e40} proves that the objective function is non-increasing. Since the constraint set of problem \textbf{P1} is strictly bounded, the convergence of Algorithm \ref{algorithmAO} is established.
\end{proof}
